using System.Collections;
using Astrea.BattleActions;
using LittleLeo.Events;
using UnityEngine;

namespace Astrea;

public class DiceInstanceOutlineHandler : ActionInstanceOutlineHandler
{
	[Header("Dice Outline Handler")]
	[SerializeField]
	private BoolEvent OnPlayActionBrightnessAnimation;

	[SerializeField]
	private BoolEvent OnSetTransitionOutlineLayerColor;

	[SerializeField]
	private VoidEvent OnSetTransitionOutlineLayerNoColor;

	[SerializeField]
	private SpriteRenderer lowQualityOutline;

	[SerializeField]
	private SpriteRenderer lowQualityOutlineAdditive;

	[Header("Brightness Animation Dice Instance")]
	[SerializeField]
	protected Material playerDiceOutlineBrightness;

	[SerializeField]
	protected Material mustUseOutlineBrightness;

	private readonly int LAYER_NO_OUTLINE = 6;

	private readonly int LAYER_BLUE_OUTLINE = 7;

	private readonly int LAYER_RED_OUTLINE = 8;

	private readonly int LAYER_TRANSITION_OUTLINE = 9;

	private bool lowQualityOutlineEnabled = true;

	private Coroutine lowQualityCoroutine;

	private Coroutine lowQualityBrightnessCoroutine;

	private DiceInstance diceInstance => actionInstance as DiceInstance;

	private ChooseDiceAction chooseDiceAction => diceInstance.ChooseDiceActionInstanceReference.Value.ActionFace.BattleAction as ChooseDiceAction;

	private void Start()
	{
		lowQualityOutline.gameObject.SetActive(value: false);
		lowQualityOutlineAdditive.gameObject.SetActive(value: false);
		lowQualityOutlineEnabled = false;
	}

	public void OnChooseDiceState()
	{
		if (!chooseDiceAction.CheckCondition(diceInstance) || !diceInstance.ActionEnabled || diceInstance.DiceState == DiceState.OnBattleActionCastSpace)
		{
			if (diceInstance.DiceState != DiceState.Dragged)
			{
				ToggleOutline(toggle: false);
			}
		}
		else if (!base.dragging)
		{
			PlayActionBrightnessAnimation();
		}
	}

	public void OnEndChooseDiceState()
	{
		if (base.diceOwnerEnum == DiceOwnerEnum.ENEMY)
		{
			ToggleOutline(toggle: false);
		}
		else if (base.diceOwnerEnum == DiceOwnerEnum.COMPANION)
		{
			if (base.actionFace.BattleAction.GetDiceActionLogic(base.actionFace.ModifiedActionValue) != null && base.actionEnabled)
			{
				ToggleOutline(toggle: true);
			}
			else
			{
				ToggleOutline(toggle: false);
			}
		}
		else
		{
			ToggleOutline(toggle: true);
		}
	}

	public void OnChoosePlayerDiceState()
	{
		if (base.diceOwnerEnum == DiceOwnerEnum.PLAYER)
		{
			OnChooseDiceState();
		}
		else if (diceInstance.DiceState != DiceState.Dragged)
		{
			ToggleOutline(toggle: false);
		}
	}

	public void OnEndChoosePlayerDiceState()
	{
		if (base.diceOwnerEnum == DiceOwnerEnum.COMPANION)
		{
			if (base.actionFace.BattleAction.GetDiceActionLogic(base.actionFace.ModifiedActionValue) != null && base.actionEnabled)
			{
				ToggleOutline(toggle: true);
			}
		}
		else if (base.diceOwnerEnum == DiceOwnerEnum.PLAYER)
		{
			ToggleOutline(toggle: true);
		}
	}

	public void OnChooseEnemyDiceState()
	{
		if (base.diceOwnerEnum == DiceOwnerEnum.ENEMY)
		{
			OnChooseDiceState();
		}
		else if (diceInstance.DiceState != DiceState.Dragged)
		{
			ToggleOutline(toggle: false);
		}
	}

	public void OnEndChooseEnemyDiceState()
	{
		OnEndChooseDiceState();
	}

	public void OnCancelActionButtonPressed()
	{
		OnEndChooseDiceState();
	}

	public void OnStartChooseActionState()
	{
		OnEndChooseDiceState();
	}

	public void OnSetTransitionOutlineLayerYellowHighlightColor()
	{
		if (lowQualityOutlineEnabled && ReferenceSingleton<BattleHandler>.Instance.CurrentActionInstance != null && ReferenceSingleton<BattleHandler>.Instance.CurrentActionInstance == actionInstance)
		{
			lowQualityOutline.material = highlightOutline;
		}
	}

	public override void ToggleOutline(bool toggle, bool animation = true)
	{
		if (!base.gameObject.activeInHierarchy)
		{
			return;
		}
		if (toggle)
		{
			if (base.diceOwnerEnum == DiceOwnerEnum.COMPANION && !diceInstance.ActionEnabled)
			{
				actionInstance.transform.SetLayerAndChildLayers(LAYER_NO_OUTLINE);
				ToggleLowQualityOutline(toggle);
				return;
			}
			if (mustUse)
			{
				actionInstance.transform.SetLayerAndChildLayers(LAYER_RED_OUTLINE);
			}
			else
			{
				actionInstance.transform.SetLayerAndChildLayers(LAYER_BLUE_OUTLINE);
			}
			ToggleLowQualityOutline(toggle);
			UpdateLowQualityOutlineMaterial();
		}
		else
		{
			actionInstance.transform.SetLayerAndChildLayers(LAYER_NO_OUTLINE);
			ToggleLowQualityOutline(toggle);
		}
	}

	private void ToggleLowQualityOutline(bool toggle)
	{
		if (lowQualityOutlineEnabled)
		{
			if (lowQualityCoroutine != null)
			{
				StopCoroutine(lowQualityCoroutine);
				lowQualityCoroutine = null;
			}
			float startValue = lowQualityOutline.Alpha();
			int targetValue = (toggle ? 1 : 0);
			lowQualityCoroutine = StartCoroutine(CoroutineUtility.CurveRoutine(0.2f, delegate(float t, float v)
			{
				lowQualityOutline.SetAlpha(Mathf.Lerp(startValue, targetValue, v));
			}, delegate
			{
				lowQualityCoroutine = null;
			}));
		}
	}

	public void SetTransitionOutlineLayer()
	{
		OnSetTransitionOutlineLayerColor.Raise(mustUse);
		actionInstance.transform.SetLayerAndChildLayers(LAYER_TRANSITION_OUTLINE);
		UpdateLowQualityOutlineMaterial();
	}

	public void UpdateTransitionOutlineLayer()
	{
		OnSetTransitionOutlineLayerColor.Raise(mustUse);
		UpdateLowQualityOutlineMaterial();
	}

	public void SetTransitionOutlineLayerNoColor()
	{
		OnSetTransitionOutlineLayerNoColor.Raise();
		actionInstance.transform.SetLayerAndChildLayers(LAYER_TRANSITION_OUTLINE);
		ToggleLowQualityOutline(toggle: false);
	}

	protected override void PlayActionBrightnessAnimation()
	{
		if (actionInstance.Discarding || diceInstance.DiceState == DiceState.Dragged)
		{
			return;
		}
		Shake();
		ToggleOutline(toggle: true);
		OnPlayActionBrightnessAnimation.Raise(mustUse);
		if (lowQualityOutlineEnabled)
		{
			if (lowQualityBrightnessCoroutine != null)
			{
				StopCoroutine(lowQualityBrightnessCoroutine);
			}
			lowQualityBrightnessCoroutine = StartCoroutine(LowQualityActionBrightnessAnimation());
		}
	}

	private void UpdateLowQualityOutlineMaterial()
	{
		if (lowQualityOutlineEnabled)
		{
			lowQualityOutline.material = (mustUse ? mustUseOutline : playerDiceOutline);
			lowQualityOutlineAdditive.material = (mustUse ? mustUseOutlineBrightness : playerDiceOutlineBrightness);
			if (lowQualityBrightnessCoroutine == null)
			{
				lowQualityOutlineAdditive.SetAlpha(0f);
			}
		}
	}

	private IEnumerator LowQualityActionBrightnessAnimation()
	{
		yield return StartCoroutine(CoroutineUtility.CurveRoutine(brightnessOnDurationReference.Value, brightnessOnCurveReference.Value, delegate(float t, float v)
		{
			lowQualityOutlineAdditive.SetAlpha(Mathf.Lerp(0f, 1f, v));
		}));
		yield return new WaitForSeconds(brightnessStayBrightDurationReference.Value);
		yield return StartCoroutine(CoroutineUtility.CurveRoutine(brightnessOffDurationReference.Value, brightnessOffCurveReference.Value, delegate(float t, float v)
		{
			lowQualityOutlineAdditive.SetAlpha(Mathf.Lerp(1f, 0f, v));
		}));
		yield return InvokeAlternatives.WaitForFrames(3);
		lowQualityBrightnessCoroutine = null;
	}
}
